const requiredFields = ['destination', 'departure', 'dates', 'groupSize', 'budget', 'email'];
const item = $input.item.json;
for (const field of requiredFields) {
  if (!item[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}
const groupSize = parseInt(item.groupSize);
if (isNaN(groupSize) || groupSize <= 0) {
  throw new Error('groupSize must be a positive number');
}
const dates = item.dates.split(' – ');
if (dates.length !== 2) {
  throw new Error('dates must be in format "YYYY-MM-DD – YYYY-MM-DD"');
}
const startDate = new Date(dates[0]);
const endDate = new Date(dates[1]);
if (isNaN(startDate.getTime()) || isNaN(endDate.getTime()) || startDate >= endDate) {
  throw new Error('Invalid dates');
}
const budget = parseFloat(item.budget.replace(/[^0-9.]/g, ''));
if (isNaN(budget) || budget <= 0) {
  throw new Error('budget must be a positive number');
}
return {
  destination: item.destination,
  departure: item.departure,
  dates: item.dates,
  groupSize: groupSize.toString(),
  budget: `$${budget.toFixed(2)}`,
  tripType: item.tripType || 'Standard',
  ageRange: item.ageRange || 'Adults',
  dayActivity: item.dayActivity || 'Beach relaxation',
  nightActivity: item.nightActivity || 'Local dining',
  email: item.email
};

const airportMap = {
  "Jamaica": { code: "MBJ", city: "Montego Bay" },
  "Honolulu": { code: "HNL", city: "Honolulu" },
  "Cancun": { code: "CUN", city: "Cancun" },
  "Aruba": { code: "AUA", city: "Aruba" },
  "Bahamas": { code: "NAS", city: "Nassau" },
  "Maldives": { code: "MLE", city: "Malé" }
};
const destination = $input.item.json.destination || "Unknown";
const mapping = airportMap[destination] || { code: "Unknown", city: destination };
return {
  airportCode: mapping.code,
  destinationCity: mapping.city,
  destination: destination
};

// Mock flight data (replace with Amadeus API if available)
const flightData = {
  "ORD-MBJ": [
    { airline: "American Airlines", layover: "Miami (MIA)", duration: "5-7 hours" },
    { airline: "United Airlines", layover: "Houston (IAH)", duration: "6-8 hours" },
    { airline: "Delta Airlines", layover: "Atlanta (ATL)", duration: "5-7 hours" }
  ],
  "ORD-HNL": [
    { airline: "American Airlines", layover: "Los Angeles (LAX)", duration: "10-12 hours" },
    { airline: "United Airlines", layover: "San Francisco (SFO)", duration: "10-12 hours" },
    { airline: "Delta Airlines", layover: "Seattle (SEA)", duration: "10-12 hours" }
  ]
};
const route = `${$input.item.json.departure}-${$input.item.json.airportCode}`;
return {
  flights: flightData[route] || [{ airline: "Unknown", layover: "Unknown", duration: "Unknown" }]
};

const groupSize = parseInt($input.item.json.groupSize);
const dates = $input.item.json.dates.split(' – ');
const nights = Math.ceil((new Date(dates[1]) - new Date(dates[0])) / (1000 * 60 * 60 * 24));
const flightsCost = 800 * groupSize; // $800/person estimate
const accommodationCost = $input.item.json.tripType === "All-inclusive resort" ? 400 * nights : 200 * nights;
const activitiesCost = 165 * groupSize; // Based on typical activities
const mealsCost = $input.item.json.tripType === "All-inclusive resort" ? 0 : 50 * groupSize * nights;
return {
  costSummary: {
    "Flights": `$${flightsCost}`,
    "Accommodation": `$${accommodationCost}`,
    "Activities": `$${activitiesCost}`,
    "Meals": `$${mealsCost}`
  }
};

